// === Tab: mySketch ===
let T, H
let colors
let palettes = [
  ["#ff4f19", "#15084d", "#5ce6e6", "#f5f2e3"],
  ["#197278", "#edddd4", "#c44536", "#5a3034"],
  ["#fde200", "#ef2626", "#5600ae", "#1c0541"],
  ["#044e9e", "#6190d3", "#fcf7ed", "#203051"],
  ["#033f63", "#7c9885", "#fedc97", "#d6d1b4"],
  ["#648381", "#575761", "#ffbf46", "#44473f"],
  ["#102542", "#f87060", "#cdd7d6", "#0a0a0a"],
	["#ed225d", "#3caf65", "#f5b800", "#0d40bf"]
]
let colorIndex
let cycle = 60 // Cycle speed
let cw, ch
let cols, rows
let showBorders = false

function setup () {
  cw = windowWidth
  ch = windowHeight
  createCanvas(cw, ch)
	T = 200
	recalculateMeasures()
  angleMode(DEGREES)
  colorIndex = floor(random(palettes.length))
  colors = palettes[colorIndex]
	pixelDensity(2)
}

function recalculateMeasures () {
	H = Math.sqrt(3) * T / 2
	cols = ceil(ch / H) + 1
  rows = ceil(cw / (T/2)) + 2
  strokeWeight(T/60)
}

function draw () {
  if (showBorders) {
    stroke(colors[3] || 0)
  } else {
    noStroke()
  }
	if (keyIsDown(DOWN_ARROW)) {
		T = max(T - 1, 50)
		recalculateMeasures()
	} else if (keyIsDown(UP_ARROW)) {
		T = min(T + 1, 400)
		recalculateMeasures()
	}

  let c = floor(frameCount / cycle) // Cycle number
  let bg = floor((c % 6) / 2)
  background(colors[2 - bg])

  push()
  translate(-T, -H/2)

  for (let j = 0; j < cols; j++) {
    for (let i = 0; i < rows; i++) {
      drawTile(i, j)
    }
  }
  pop()
}

let drawTile = (x, y) => {
  var c = floor(frameCount / cycle)
  push()
  noFill()
  translate(...getCenter(x, y))
  rectMode(CENTER)
  let isOdd = x % 2 === y % 2
  let sc = floor((c % 6) / 2)
  let invert = floor(c / 6) % 2 === 1
  if (sc === 0) {
    d(!isOdd, 0, 0, invert)
    d(isOdd, 1, 1, invert)
  } else if (sc === 1) {
    d(!isOdd, 1, 0, invert)
    d(isOdd, 0, 2, invert, T/2, H/3)
  } else {
    d(isOdd, 0, 1, invert)
    d(isOdd, 1, 2, invert, T/2, H/3)
  }
  pop()
}

let d = (doDraw, cycleIndex, colorIndex, invert = false, tx = 0, ty = 0) => {
  if (!doDraw) {
    return
  }
  var c = floor(frameCount / cycle)
  let w = T/2
  let h = H *2/3
  push()
  translate(tx, ty)
  fill(colors[colorIndex])
  let ia = floor((c % 6) / 2)
  if (invert) {
    ia = -ia
  }
  let initialAngle = ia * 60
  let rot = 60
  if (invert) { rot = -rot }

  if (c % 2 === cycleIndex) {
    rotate(initialAngle +
      ease(map(frameCount % cycle, 0, cycle, 0, 1)) * rot
    )
	} else {
    if (c % 2 < cycleIndex) {
      rotate(initialAngle)
    } else {
      rotate(initialAngle + rot)
    }
  }
  rect(0, 0, w, h)
  pop()
}

let getCenter = (x, y) => {
  return [
    (x * T / 2) + T / 2,
    (x + y) % 2 !== 0 ?
    (y * H) + (H / 3) :
    (y * H) + (H * 2 / 3)
  ]
}

function mouseClicked () {
  let nc = floor(random(palettes.length))
  let _wG_1 = 0; while ((nc === colorIndex) && ++_wG_1 < 20000) {
    nc = floor(random(palettes.length))
  }
  colorIndex = nc
  colors = palettes[colorIndex]
}

function keyPressed () {
  if (keyCode === 32) { // Space bar
    showBorders = !showBorders
  }
}

function ease(x) {
  // Ease in out back
  let c1 = 1.85
  let c2 = c1 * 2.3

  return x < 0.5
    ? (Math.pow(2 * x, 2) * ((c2 + 1) * 2 * x - c2)) / 2
    : (Math.pow(2 * x - 2, 2) * ((c2 + 1) * (x * 2 - 2) + c2) + 2) / 2;
}
